package com.runecraft.combat;

import net.neoforged.neoforge.common.NeoForge;
import net.neoforged.neoforge.event.entity.living.LivingKnockBackEvent;

/**
 * OSRS hits never push (round 41, // playability: OSRS has no knockback on a hit; vanilla pushes 0.4 on every damage source
 * that isn't in {@code #minecraft:no_knockback}, and {@code runecraft:osrs_hit} isn't, since that tag is generated by
 * tools/gen_worldgen.py). While {@link CombatHandler#applyingOsrsHit()} is true, a knockback on anyone, player or monster, is
 * cancelled. Pushes a mechanic makes on purpose (the KNOCKBACK special, Obor's slam, Callisto, Muspah's spikes...) run outside
 * {@code applyDamage} and still work.
 */
public final class OsrsKnockback {
    private static boolean registered;

    private OsrsKnockback() {
    }

    public static void register() {
        if (registered) {
            return;
        }
        registered = true;
        NeoForge.EVENT_BUS.addListener(LivingKnockBackEvent.class, e -> {
            if (!e.getEntity().level().isClientSide() && CombatHandler.applyingOsrsHit()) {
                e.setCanceled(true);
            }
        });
    }
}
